NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'James'

CHAPTERS = {
    1: {
        1: 'Jakobus, /ein Knecht Gottes und des Herrn Jesus Christus, /an die zwölf Stämme in der Zerstreuung: /Seid gegrüßt!',
        2: 'Haltet es für lauter Freude, meine Geschwister, wann immer ihr in verschiedene Versuchungen geratet,',
        3: 'und erkennt, dass die Bewährung eures Glaubens Standhaftigkeit bewirkt.',
        4: 'Die Standhaftigkeit wiederum soll ein vollkommenes Werk [zur Folge] haben, damit ihr vollkommen und vollständig seid und in keinerlei [Hinsicht] Mangel habt.',
        5: 'Wenn es nun jemandem von euch an Weisheit mangelt, dann soll er sie von Gott erbitten, der allen großzügig gibt und [dabei] nicht schimpft, dann wird sie ihm gegeben werden.',
        6: 'Er soll aber im Glauben bitten und nichts anzweifeln; denn wer zweifelt, gleicht der Brandung des Meeres, die vom Wind bewegt und hin und her geworfen wird.',
        7: 'Jener Mensch soll nämlich nicht meinen, dass er etwas vom Herrn erhalten wird,',
        8: '[ist er doch] ein unentschlossener Mann, wankelmütig auf allen seinen Wegen.',
        9: 'Nun soll sich der niedrige Bruder seiner hohen Stellung rühmen,',
        10: 'der reiche aber seiner Niedrigkeit, weil er wie eine Blüte des Grases vergehen wird.',
        11: 'Denn die Sonne geht mit [ihrer] Hitze auf, und sie trocknet das Gras aus, und seine Blüte fällt, und die Schönheit ihres Anblicks vergeht; so wird auch der Reiche bei seinen Unternehmungen verblühen.',
        12: 'Beglückwünschenswert [ist] der Mann, der die Versuchung erduldet, weil er – wenn er ‹sich bewährt hat› – den Siegeskranz des Lebens erhalten wird, den er denen verheißen hat, die ihn lieben.',
        13: 'Niemand, der versucht wird, soll sagen: „Ich werde von Gott versucht!“Denn Gott ist durch das Schlechte nicht versucht, und er selbst versucht niemanden.',
        14: 'Vielmehr ein jeder wird versucht, indem er von der eigenen Begierde fortgerissen und gelockt wird.',
        15: 'Danach – wenn die Begierde empfangen hat – gebiert sie Sünde, die Sünde wiederum – wenn sie gereift ist – bringt den Tod hervor.',
        16: 'Lasst euch nicht irreführen, meine geliebten Geschwister!',
        17: 'Jede gute Gabe und jedes vollkommene Geschenk kommt von oben herab, vom Vater der Lichter, bei dem es keine Veränderung oder Wechselhaftigkeit gibt.',
        18: 'Da er es wollte, hat er uns durch das Wort der Wahrheit hervorgebracht, damit wir eine Art Erstlingsfrucht seiner Geschöpfe sind.',
        19: 'Versteht, meine geliebten Geschwister: Jeder Mensch sei nun schnell zum Hören, langsam zum Reden, langsam zum Zorn!',
        20: 'Denn der Zorn eines Mannes bewirkt nicht die Gerechtigkeit Gottes.',
        21: 'Darum: Nachdem ihr alle Unmoral und ein Übermaß an Bosheit abgelegt habt, empfangt mit Sanftmut das eingepflanzte Wort, das eure Seelen retten kann!',
        22: 'Werdet nun Täter des Wortes und nicht bloß Hörer, die sich selbst beschwindeln!',
        23: 'Denn wenn jemand ein Hörer des Wortes ist und kein Täter, dann gleicht er einem Mann, der sein eigentliches Gesicht im Spiegel betrachtet;',
        24: 'denn er betrachtet sich selbst und geht dann weg, und gleich darauf vergisst er, welche Art [von Mensch] er war.',
        25: 'Wer sich aber in das vollkommene Gesetz – das der Freiheit – vertieft und [dort] verweilt, weil er kein vergesslicher Hörer ist, sondern ein Täter des Werks, der ist beglückwünschenswert in seinem Tun.',
        26: 'Wenn jemand religiös zu sein meint, obwohl er seine Zunge nicht zügelt, sondern sein Herz täuscht, dessen Religiosität [ist] bedeutungslos.',
        27: 'Reine und unbefleckte Religiosität bei [unserem] Gott und Vater ist Folgendes: sich um Waisen und Witwen in ihrer Bedrängnis zu kümmern [und] sich selbst unbefleckt vor der Welt zu bewahren.',
    },
    2: {
        1: 'Meine Geschwister, haltet den Glauben an unseren glorreichen Herrn Jesus Christus ‹frei von› Parteilichkeit!',
        2: 'Denn wenn in eure Zusammenkunft ein Mann kommt, goldberingt und in feiner Kleidung, und es kommt auch ein Armer in verdreckter Kleidung herein,',
        3: 'ihr seht aber auf den, der die feine Kleidung trägt, und ihr sagt: „Setz du dich einfach hier hin!“, und zu dem Armen sagt ihr: „Stell du dich hin oder setze dich dort unter meinem Schemel!“,',
        4: 'unterscheidet ihr dann nicht unter euch und seid Richter mit bösen Überlegungen geworden?',
        5: 'Hört zu, meine geliebten Geschwister: Hat Gott nicht die Armen in der Welt erwählt, reich im Glauben und Erben des Königreiches [zu sein], das er denen verheißen hat, die ihn lieben?',
        6: 'Ihr aber habt den Armen bloßgestellt! Beuten euch nicht die Reichen aus, und dann zerren sie euch vor Gericht?',
        7: 'Lästern nicht sie den guten Namen, der über euch ausgerufen wurde?',
        8: 'Wenn ihr jedoch das königliche Gesetz ausführt gemäß der Schrift: „Liebe deinen Nächsten wie dich selbst!“, dann handelt ihr richtig;',
        9: 'aber wenn ihr parteiisch seid, bewirkt ihr eine Sünde und werdet vom Gesetz als Übertreter überführt.',
        10: 'Denn wer das gesamte Gesetz hält, aber in einer einzigen [Sache] strauchelt, ist aller [Übertretungen] schuldig geworden.',
        11: 'Denn der gesagt hat: „Du sollst nicht ehebrechen!“, hat auch gesagt: „Du sollst nicht morden!“Und wenn du nicht ehebrichst, aber mordest, dann bist du ein Übertreter des Gesetzes geworden.',
        12: 'So sprecht und so handelt, als ob ihr durch das Gesetz der Freiheit gerichtet zu werden droht.',
        13: 'Denn das Gericht [ist] erbarmungslos für den, der nicht Erbarmen übt; Erbarmen triumphiert über das Gericht.',
        14: 'Was [ist] der Nutzen, meine Geschwister, wenn jemand behauptet, Glauben zu haben, aber keine Werke [aufzuweisen] hat? Kann etwa der Glaube ihn retten?',
        15: 'Wenn ein Bruder oder eine Schwester nackt sind und ihnen die tägliche Nahrung fehlt,',
        16: 'aber jemand von euch zu ihnen sagt: „Geht hin in Frieden, wärmt euch und sättigt euch!“, und ihr ihnen nicht gebt, was der Körper nötig [hat], was [ist] der Nutzen?',
        17: 'So ist auch der Glaube, wenn er keine Werke [vorzuweisen] hat, an und für sich tot.',
        18: 'Doch jemand wird sagen: „Du hast Glauben, und ich habe Werke. Zeige mir deinen Glauben ohne die Werke, dann werde ich dir aufgrund meiner Werke den Glauben zeigen.“',
        19: 'Du glaubst, dass Gott einer ist, das tust du zu Recht! Auch die Dämonen glauben es, und sie erschaudern.',
        20: 'Willst du nun erkennen, oh du eitler Mensch, dass der Glaube ohne die [entsprechenden] Werke nutzlos ist?',
        21: 'Wurde Abraham, unser Vater, nicht aufgrund von Werken gerechtfertigt, als er Isaak, seinen Sohn, auf dem Altar darbrachte?',
        22: 'Du siehst, dass der Glaube mit seinen Werken wirkt und aufgrund der Werke der Glaube vervollkommnet wird.',
        23: 'Und die Schrift wurde erfüllt, die besagt: „Und Abraham glaubte Gott, und es wurde ihm zur Gerechtigkeit angerechnet“, und er wurde ein „Freund Gottes“genannt.',
        24: 'Ihr seht, dass ein Mensch aufgrund von Werken gerechtfertigt wird und nicht nur aufgrund des Glaubens.',
        25: 'Und wurde nicht genauso auch Rahab, die Prostituierte, aufgrund von Werken gerechtfertigt, als sie die Boten empfing und auf einem anderen Weg hinausbrachte?',
        26: 'Denn wie der Körper ohne Geist tot ist, so ist auch der Glaube ohne Werke tot.',
    },
    3: {
        1: 'Nicht viele sollten Lehrer werden, meine Geschwister, da ihr wisst, dass wir ein härteres Gericht erhalten werden.',
        2: 'Wir alle straucheln nämlich häufig. Wenn jemand im Wort nicht strauchelt, dann [ist] dieser ein vollkommener Mensch, fähig auch den gesamten Körper zu zügeln.',
        3: 'Aber wenn wir die Zügel in das Maul der Pferde tun, damit sie uns gehorchen, dann lenken wir auch ihren gesamten Körper.',
        4: 'Siehe!, auch die Schiffe: Obwohl sie so groß sind und von starken Winden angetrieben werden, werden sie vom kleinsten Ruder gelenkt, wohin der Drang des Steuernden will.',
        5: 'So ist auch die Zunge ein kleiner Körperteil, aber sie rühmt sich großer [Dinge]. Siehe!, ein so kleines Feuer verbrennt einen so großen Wald.',
        6: 'Auch die Zunge [ist] ein Feuer: Als die Welt der Ungerechtigkeit wird die Zunge – unter unseren Körperteilen eingesetzt, die den gesamten Körper befleckt und das Rad der Geburt entzündet und von der Hölle entzündet wird.',
        7: 'Denn jede Art von Säugetieren und Vögeln, Reptilien und Meerestieren wird gebändigt und ist gebändigt durch die menschliche Art;',
        8: 'die Zunge aber kann kein Mensch bändigen, [sie ist] ein rastloses Übel, voller tödlichem Gift.',
        9: 'Mit ihr loben wir [unseren] Herrn und Vater, und mit ihr verfluchen wir die Menschen, die nach dem Ebenbild Gottes gemacht sind;',
        10: 'aus demselben Mund gehen Segen und Fluch hervor. Meine Geschwister, diese [Dinge] dürfen so nicht passieren!',
        11: 'Sprudelt etwa die Quelle aus derselben Öffnung Süßes und Bitteres?',
        12: 'Kann etwa ein Feigenbaum, meine Geschwister, Oliven produzieren oder ein Weinberg Feigen? Auch kann salziges nicht süßes Wasser produzieren.',
        13: 'Wer [ist] weise und einsichtig unter euch? Er soll seine Werke durch [seinen] guten Lebenswandel zeigen, mit der Demut der Weisheit.',
        14: 'Aber wenn ihr bitteren Neid und Selbstsucht in euren Herzen habt, dann prahlt nicht und lügt nicht gegen die Wahrheit!',
        15: 'Dies ist nicht die Weisheit, die von oben herabkommt, sondern eine irdische, natürliche, dämonische.',
        16: 'Denn wo Neid und Selbstsucht [herrschen], da [gibt es] Unordnung und lauter schlechte Taten.',
        17: 'Die Weisheit von oben aber ist vor allem unschuldig, dann friedfertig, sanft, gehorsam, voller Barmherzigkeit und guter Früchte, unparteiisch, ungeheuchelt.',
        18: 'Die Frucht der Gerechtigkeit wiederum wird in Frieden für die gesät, die Frieden stiften.',
    },
    4: {
        1: 'Woher [stammen] Kämpfe und woher [stammen] Streitigkeiten unter euch? Nicht daher: aufgrund eurer Vergnügungen, die in euren Gliedern streiten?',
        2: 'Ihr begehrt, und doch habt ihr nicht; ihr mordet und ihr ereifert euch, und doch könnt ihr nichts erreichen; ihr bekämpft und bekriegt euch; ihr habt nicht, weil ihr nicht bittet,',
        3: 'ihr bittet und doch erhaltet ihr nichts, weil ihr in schlechter Weise bittet, um es in euren Vergnügungen zu verschwenden.',
        4: 'Ihr untreuen [Eheleute], wisst ihr nicht, dass die Freundschaft zur Welt Feindschaft Gottes bedeutet? Wer auch immer also ein Freund der Welt sein will, macht sich zu einem Feind Gottes.',
        5: 'Oder meint ihr, dass die Schrift umsonst sagt: „Mit Eifersucht sehnt er sich nach dem Geist, den er in uns wohnen ließ“,',
        6: 'er aber [umso] größere Gnade gibt? Darum sagt sie: „Gott widersteht den Hochmütigen, den Niedrigen aber gibt er Gnade.“',
        7: 'Unterwerft euch also Gott, widersteht aber dem Teufel, dann wird er von euch fliehen!',
        8: 'Nähert euch Gott, dann wird er sich euch nähern! Reinigt [eure] Hände, ihr Sünder, und reinigt [eure] Herzen, ihr Unentschlossenen!',
        9: 'Klagt und trauert und weint! Euer Gelächter soll in Klage verwandelt werden und eure Freude in Niedergeschlagenheit!',
        10: 'Fügt euch demütig vor dem Herrn, dann wird er euch erhöhen!',
        11: 'Verleumdet einander nicht, Geschwister! Wer einen Bruder verleumdet oder seinen Bruder richtet, verleumdet das Gesetz und richtet das Gesetz; aber wenn du das Gesetz richtest, bist du kein Täter des Gesetzes, sondern [sein] Richter.',
        12: 'Einer ist Gesetzgeber und Richter, der retten und zunichtemachen kann; du aber, wer bist du, der du den Nächsten richtest?',
        13: 'Auf jetzt, die ihr sagt: „Heute oder morgen werden wir in die und die Stadt gehen und dort ein Jahr verbringen und Handel treiben und Gewinn machen“,',
        14: 'die ihr nicht wisst, was [die Umstände] des morgigen [Tages] [sein werden], von welcher Art [ist] euer Leben? Ihr seid nämlich ein Dunst, der für kurze Zeit sichtbar ist und dann verschwindet.',
        15: 'Stattdessen sollt ihr sagen: „Wenn der Herr will, dann werden wir leben und dieses oder jenes tun.“',
        16: 'Tatsächlich aber brüstet ihr euch mit eurer Arroganz; alles derartige Brüsten ist böse.',
        17: 'Wer also Gutes zu tun weiß und es nicht tut, für den ist es eine Sünde.',
    },
    5: {
        1: 'Auf jetzt, ihr Reichen, weint und heult über euer Elend, das kommt.',
        2: 'Euer Reichtum ist verrottet, und eure Gewänder sind löchrig geworden.',
        3: 'Euer Gold und Silber sind verrostet, und ihr Rost wird euch zum Zeugnis sein und euer Fleisch wie Feuer vertilgen; ihr habt [Reichtümer] gesammelt in den letzten Tagen.',
        4: 'Siehe!, der von euch zurückgehaltene Lohn der Arbeiter, die eure Felder beackern, schreit [zum Himmel], und die Rufe der Erntehelfer sind an die Ohren des Herrn Zebaot gekommen.',
        5: 'Ihr habt auf der Erde geschwelgt und verschwenderisch gelebt, ihr habt eure Herzen am Tag der Schlachtung gemästet.',
        6: 'Ihr habt den Gerechten verurteilt und ermordet; er widersteht euch nicht.',
        7: 'Habt also Geduld, Geschwister, bis zur Ankunft des Herrn. Siehe!, der Bauer erwartet die kostbare Frucht der Erde, indem er Geduld damit hat, bis sie frühen und späten [Regen] erhalten hat.',
        8: 'Habt auch ihr Geduld, stärkt eure Herzen, weil die Ankunft des Herrn nahegekommen ist.',
        9: 'Seufzt nicht gegeneinander, Geschwister, damit ihr nicht gerichtet werdet; siehe!, der Richter steht vor den Toren.',
        10: 'Geschwister, nehmt euch die Propheten, die im Namen des Herrn geredet haben, als Beispiel für Leidensbereitschaft und Geduld.',
        11: 'Siehe!, wir beglückwünschen diejenigen, die standhaft geblieben sind – von der Standhaftigkeit Ijobs habt ihr gehört, und das Ende des Herrn habt ihr gesehen, dass der Herr mitfühlend und barmherzig ist.',
        12: 'Vor allem aber, meine Geschwister, schwört nicht, weder bei dem Himmel noch bei der Erde noch irgendeinen anderen Eid! Es soll aber euer „Ja“ein „Ja“sein, und das „Nein“ein „Nein“, damit ihr nicht unter ein Gericht fallt.',
        13: 'Erleidet jemand unter euch Schlechtes, dann soll er beten! Ist jemand fröhlich, dann soll er Psalmen singen!',
        14: 'Ist jemand unter euch krank, dann soll er die Ältesten der Gemeinde herbeirufen, und sie sollen über ihm beten und ihn im Namen des Herrn mit Öl behandeln.',
        15: 'Und das Gebet des Glaubens wird den Kranken retten, und der Herr wird ihn aufrichten; und wenn er Sünden begangen hat, wird ihm vergeben werden.',
        16: 'Bekennt also einander die Sünden und betet füreinander, damit ihr geheilt werdet. Das wirksame Flehen eines Gerechten vermag viel.',
        17: 'Elija war ein Mensch, uns gleich empfindend, und er betete inständig, dass es nicht regnen würde, und es regnete nicht über das Land drei Jahre und sechs Monate lang.',
        18: 'Und wieder betete er, und der Himmel schenkte Regen und die Erde ließ ihre Frucht sprießen.',
        19: 'Meine Geschwister, wenn jemand unter euch von der Wahrheit abgeirrt ist und ihn jemand [anderes] zurückholt,',
        20: 'dann soll er erkennen, dass derjenige, der einen Sünder von seinem Irrweg zurückholt, seine Seele vor dem Tod retten wird, und er wird eine Menge Sünden bedecken.',
    },
}
